    G.v.weeklyFighter = Math.floor(num((num(mod(num((num(sin(num((num(sin(num((num(sin(num((num((num(G.v.myCurrentDay) + num((num(G.v.weeklyRounds) * 10000)))) * 6254.65)))) * 482920.98)))) * 478962.4824)))) * 54545.4584)), 48)) + 1)));
